package dev.smpcristalix.pvpcombat.listener;import org.bukkit.Material;import org.bukkit.enchantments.Enchantment;import org.bukkit.event.*;import org.bukkit.event.enchantment.EnchantItemEvent;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.ItemStack;import java.util.*;/** Mace: only Wind Burst I, Density I and Breach I. */public final class MaceListener implements Listener{private static final Set<String> ALLOWED=Set.of("wind_burst","density","breach");@EventHandler(ignoreCancelled=true)public void onEnchant(EnchantItemEvent e){if(e.getItem().getType()==Material.MACE&&!allowed(e.getEnchantsToAdd())){e.setCancelled(true);e.getEnchanter().sendMessage("§cДля булавы разрешены только Порыв ветра I, Плотность I и Пробитие I.");}}@EventHandler(ignoreCancelled=true)public void onClick(InventoryClickEvent e){ItemStack i=e.getCurrentItem();if(i!=null&&i.getType()==Material.MACE&&!allowed(i.getEnchantments()))e.setCancelled(true);}private boolean allowed(Map<Enchantment,Integer> map){for(var x:map.entrySet())if(!ALLOWED.contains(x.getKey().getKey().getKey())||x.getValue()>1)return false;return true;}}
